// app/blog/[slug]/page.tsx
import { notFound } from "next/navigation";

const posts = [
  { slug: "primeiro-post", titulo: "Meu primeiro post", texto: "..." },
  { slug: "novidades", titulo: "Novidades do Next.js", texto: "..." },
];

// Roda no build: devolve um objeto para cada pagina a gerar
export async function generateStaticParams() {
  return posts.map((post) => ({ slug: post.slug }));
}

// false = slug fora da lista vira 404 (o padrao e true)
export const dynamicParams = false;

export default async function Post({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const post = posts.find((p) => p.slug === slug);
  if (!post) notFound();

  return (
    <article>
      <h1>{post.titulo}</h1>
      <p>{post.texto}</p>
    </article>
  );
}

// lib/tarefas.ts -- "banco" simples num arquivo JSON
import { readFile, writeFile } from "fs/promises";

export interface Tarefa {
  id: number;
  titulo: string;
  feita: boolean;
}

const ARQUIVO = "tarefas.json";

export async function lerTarefas(): Promise<Tarefa[]> {
  try {
    return JSON.parse(await readFile(ARQUIVO, "utf-8"));
  } catch {
    return [];   // o arquivo ainda nao existe
  }
}

export async function salvarTarefas(tarefas: Tarefa[]) {
  await writeFile(ARQUIVO, JSON.stringify(tarefas, null, 2));
}

// app/tarefas/actions.ts
"use server";   // todas as funcoes deste arquivo sao Server Actions

import { revalidatePath } from "next/cache";
import { lerTarefas, salvarTarefas } from "@/lib/tarefas";

export async function criarTarefa(formData: FormData) {
  const titulo = String(formData.get("titulo") ?? "").trim();
  if (!titulo) return;   // ignora titulo vazio

  const tarefas = await lerTarefas();
  // aqui nao e estado do React: pode alterar o array
  tarefas.push({ id: Date.now(), titulo, feita: false });
  await salvarTarefas(tarefas);
  revalidatePath("/tarefas");   // a pagina mostra a lista nova
}

export async function marcarFeita(id: number) {
  const tarefas = await lerTarefas();
  const tarefa = tarefas.find((t) => t.id === id);
  if (tarefa) tarefa.feita = true;
  await salvarTarefas(tarefas);
  revalidatePath("/tarefas");
}

export async function excluirTarefa(id: number) {
  const tarefas = await lerTarefas();
  await salvarTarefas(tarefas.filter((t) => t.id !== id));
  revalidatePath("/tarefas");
}

// app/tarefas/page.tsx -- Server Component
import { lerTarefas } from "@/lib/tarefas";
import { criarTarefa, marcarFeita, excluirTarefa } from "./actions";

export const dynamic = "force-dynamic";   // le o arquivo a cada visita

export default async function Tarefas() {
  const tarefas = await lerTarefas();

  return (
    <main>
      <form action={criarTarefa}>
        <input name="titulo" placeholder="Nova tarefa" required />
        <button type="submit">Adicionar</button>
      </form>

      <ul>
        {tarefas.map((t) => (
          <li key={t.id}>
            {t.feita ? <s>{t.titulo}</s> : t.titulo}
            <form action={marcarFeita.bind(null, t.id)}>
              <button type="submit">Feita</button>
            </form>
            <form action={excluirTarefa.bind(null, t.id)}>
              <button type="submit">Excluir</button>
            </form>
          </li>
        ))}
      </ul>
    </main>
  );
}

// app/contato/actions.ts
"use server";

export interface Resultado {
  ok: boolean;
  mensagem: string;
}

export async function enviarMensagem(
  anterior: Resultado | null,
  formData: FormData
): Promise<Resultado> {
  const nome = String(formData.get("nome") ?? "").trim();
  const email = String(formData.get("email") ?? "").trim();

  // a validacao no servidor e a que vale: nao da para burlar
  if (nome.length < 3) {
    return { ok: false, mensagem: "Informe o nome (minimo de 3 letras)." };
  }
  if (!email.includes("@")) {
    return { ok: false, mensagem: "Informe um e-mail valido." };
  }

  // aqui a mensagem seria salva no banco ou enviada por e-mail
  return { ok: true, mensagem: `Obrigado, ${nome}! Mensagem recebida.` };
}

// app/contato/FormContato.tsx
"use client";

import { useActionState } from "react";
import { enviarMensagem } from "./actions";

export default function FormContato() {
  const [resultado, acao, enviando] = useActionState(enviarMensagem, null);

  return (
    <form action={acao}>
      <input name="nome" placeholder="Nome" />
      <input name="email" placeholder="E-mail" />
      <button type="submit" disabled={enviando}>
        {enviando ? "Enviando..." : "Enviar"}
      </button>

      {resultado && (
        <p className={resultado.ok ? "sucesso" : "erro"}>
          {resultado.mensagem}
        </p>
      )}
    </form>
  );
}

// app/contato/page.tsx -- Server Component
import FormContato from "./FormContato";

export default function Contato() {
  return (
